const { app, BrowserWindow } = require('electron');
const path = require('node:path');
app.whenReady().then(async () => {
    const win = new BrowserWindow({ show: false, webPreferences: { partition: 'ui-test-'+Date.now(), sandbox: true, contextIsolation: true, preload: path.join(__dirname,'ui-preload.cjs') } });
    await win.loadFile(path.resolve(process.argv.at(-1), 'dist/index.html'));
    win.webContents.debugger.attach('1.3');
    await win.webContents.debugger.sendCommand('Emulation.setDeviceMetricsOverride', { width: 1920, height: 1080, deviceScaleFactor: 1, mobile: false });
    const result = await win.webContents.executeJavaScript(`(async () => {
        const wait = async check => { for(let i=0;i<200;i++){ if(check())return; await new Promise(r=>setTimeout(r,20)); } throw Error('Timed out: '+check); };
        const assert = (value,message) => {if(!value) throw Error(message);};
        const button = (name,root=document) => [...root.querySelectorAll('button')].find(b=>b.textContent.trim()===name);
        const fill = (id,value) => { const input=document.getElementById(id); const setter=Object.getOwnPropertyDescriptor(input.tagName==='TEXTAREA'?HTMLTextAreaElement.prototype:HTMLInputElement.prototype,'value').set; setter.call(input,value); input.dispatchEvent(new Event('input',{bubbles:true})); };
        await wait(()=>button('Save and finish setup'));
        fill('project-name','Demo workspace');
        fill('name-default','Preview environment');
        fill('url-default','https://app.example.test');
        button('Save and finish setup').click();
        await wait(()=>document.body.textContent.includes('Saved locally.'));
        assert(document.querySelector('h1').textContent==='Demo workspace','Project name was not saved');
        assert(document.getElementById('run-profile').textContent.includes('Preview environment'),'Profile was not updated');
        assert(document.body.textContent.includes('.spec-runner/categories.json'),'Commit reminder missing file names');
        document.querySelector('[aria-label="Dismiss commit reminder"]').click();
        button('Categories').click();
        await wait(()=>document.querySelector('article'));
        const card=document.querySelector('article[aria-label="Category Account"]');
        const height=card.getBoundingClientRect().height;
        card.querySelector('input').click();
        await wait(()=>card.textContent.includes('2 of 2 selected'));
        assert(card.getBoundingClientRect().height===height,'Selecting a category expanded it');
        assert(getComputedStyle(card.parentElement).gridTemplateColumns.split(' ').length===4,'Grid should fit four columns');
        assert(button('View specs in Account',card).getBoundingClientRect().height<=28,'Category buttons too large');
        button('View specs in Account',card).click();
        await wait(()=>document.querySelector('[role=dialog]'));
        let dialog=document.querySelector('[role=dialog]');
        button('Deselect all',dialog).click();
        await wait(()=>dialog.textContent.includes('0 of 2 selected'));
        button('Select all',dialog).click();
        await wait(()=>dialog.textContent.includes('2 of 2 selected'));
        button('Done',dialog).click();
        await wait(()=>!document.querySelector('[role=dialog]'));
        button('Edit category Account',card).click();
        await wait(()=>document.getElementById('category-name'));
        fill('category-name','Smoke checks');
        button('Save category',document.querySelector('[role=dialog]')).click();
        await wait(()=>document.body.textContent.includes('Saved locally.'));
        assert(document.body.textContent.includes('.spec-runner/categories.json'),'Category save reminder missing');
        document.querySelector('[aria-label="Dismiss commit reminder"]').click();
        button('Settings').click();
        await wait(()=>document.getElementById('project-name'));
        const follow=[...document.querySelectorAll('label')].find(l=>l.textContent.includes('Follow new output automatically'));
        follow.querySelector('input').click();
        assert(!document.body.textContent.includes('Saved locally.'),'Personal preference created commit reminder');
        const help=document.querySelector('[aria-label="About local environment files"]');
        help.click();
        await wait(()=>document.querySelector('[role=tooltip]'));
        assert(document.querySelector('[role=tooltip]').textContent.includes('read only when a run starts'),'Tooltip missing');
        help.dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
        await wait(()=>!document.querySelector('[role=tooltip]'));
        document.querySelector('[aria-label="Enable chrome"]').click();
        document.querySelector('[aria-label="Enable edge"]').click();
        document.querySelector('[aria-label="Enable firefox"]').click();
        await wait(()=>document.querySelector('[aria-label="Enable electron"]').disabled);
        assert([...document.getElementById('browser').options].length===4,'Draft browser changes applied before saving');
        fill('name-default','Test environment');
        button('Save project settings').click();
        await wait(()=>document.body.textContent.includes('Saved locally.'));
        assert(document.getElementById('run-profile').textContent.includes('Test environment'),'Saved environment not reflected in controls');
        const savedProject=await window.specRunner.project();
        assert(JSON.stringify(savedProject.config.browsers)===JSON.stringify(['electron']),'Browser choices were not saved');
        assert([...document.getElementById('browser').options].map(option=>option.value).join(',')==='electron','Disabled browsers remain in run controls');
        assert(document.getElementById('browser').value==='electron','Removed preferred browser was not replaced');
        assert([...document.getElementById('preferred-browser').options].map(option=>option.value).join(',')==='electron','Personal browser choices ignored project settings');
        assert(document.body.textContent.includes('spec-runner.config.json'),'Browser save did not show a commit reminder');
        button('Categories').click();
        await wait(()=>button('Run 2 specs · Test environment'));
        await wait(()=>!button('Run 2 specs · Test environment').disabled);
        button('Run 2 specs · Test environment').click();
        await wait(()=>button('Stop run'));
        assert(document.querySelector('pre').textContent==='Example output\\n','Run output missing');
        assert(button('Open log').disabled,'Log opened before the active run finished');
        button('Stop run').click();
        await wait(()=>button('Open log')&&!button('Open log').disabled);
        assert(!button('Save full log'),'Duplicate save action remains');
        button('Open log').click();
        await wait(()=>!button('Open log').disabled);
        assert((await window.specRunner.project()).logOpened,'Open log did not call the desktop API');
        return 'Setup, profile editing, category selection/editing, commit reminders, personal preferences, accessible help, run and stop, browser restrictions and fallback, open log control, and 1080p density passed.';
    })()`);
    console.log(result); app.exit(0);
}).catch(error=>{console.error(error);app.exit(1);});
